Você quer conferir agora a tela de erro do Início, sem depender da sorte. O que mudar no `src/api/simulacao.js` abaixo?

```javascript
export const CHANCE_DE_ERRO = 0.3;

export function simularRede(espera = 1500) {
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (Math.random() < CHANCE_DE_ERRO) reject(new ApiError(503));
      else resolve();
    }, espera);
  });
}
```

